import { ref } from 'vue';
export class Modal {
    title;
    message;
    subMessage;
    isOpen;
    constructor(title, message, subMessage) {
        this.title = title;
        this.message = message;
        this.subMessage = subMessage;
        this.isOpen = ref(false);
    }
    open() {
        this.isOpen.value = true;
    }
    close() {
        this.isOpen.value = false;
    }
    rightButton() {
        this.close();
    }
}
