import dayjs from "dayjs";
export class HistoryModel {
    human_id;
    name;
    browsed_at;
    constructor(data) {
        this.human_id = data.human_id || "";
        this.name = data.name || "";
        this.browsed_at = data.browsed_at
            ? dayjs(data.browsed_at).format("YYYY/MM/DD HH:mm:ss")
            : "";
    }
}
export class HistoryListModel {
    contents;
    constructor() {
        this.contents = [];
    }
    init(data) {
        this.clear();
        this.contents.push(...data.map((d) => {
            return new HistoryModel(d);
        }));
    }
    clear() {
        this.contents.splice(0);
    }
}
