import { REPORT_CONTENT_TYPE } from '/@/js/contarcts/ReportContentType';
export class ReportForm {
    id;
    name;
    diary;
    required;
    static TYPE_TEXT = REPORT_CONTENT_TYPE.TEXT;
    static TYPE_TEXTAREA = REPORT_CONTENT_TYPE.TEXTAREA;
    static TYPE_CHOICE = REPORT_CONTENT_TYPE.CHOICE;
    static TYPE_SELECT = REPORT_CONTENT_TYPE.SELECT;
    static TYPE_DATE = REPORT_CONTENT_TYPE.DATETIME;
    static TYPE_TENKI = REPORT_CONTENT_TYPE.TENKI;
    static TYPE_IMAGE = REPORT_CONTENT_TYPE.IMAGE;
    static TYPE_MOVIE = REPORT_CONTENT_TYPE.MOVIE;
    constructor(res) {
        this.id = res.id || 0;
        this.name = res.name || '';
        this.diary = new ReportContents(res.diary || []);
        this.required = res.required ? true : false;
    }
    static getInstance() {
        return new ReportForm({
            id: 0,
            name: '',
            required: false,
            diary: ReportContents.getInstance(),
        });
    }
}
export class ReportContents {
    contents;
    contentsIndex;
    constructor(res) {
        this.contents = res.contents.map((r) => {
            return new ReportContentsItem(r);
        });
        this.contentsIndex = res.contentsIndex;
    }
    // コンテンツ(選択肢)を追加
    addContents(newContents) {
        newContents.key = this.contentsIndex;
        this.contents.push(newContents);
        this.contentsIndex++;
    }
    // コンテンツ(選択肢)を削除
    deleteContents(index) {
        this.contents.splice(index, 1);
    }
    // コンテンツの中に同じタイトルのものがあるかどうか
    hasTitle(title) {
        const result = this.contents.filter((c) => c.title === title);
        return result.length > 1; // 2以上であれば重複あり
    }
    // コンテンツを持っている
    hasContents() {
        return this.contents.length > 0;
    }
    static getInstance() {
        return new ReportContents({
            contentsIndex: 0,
            contents: [],
        });
    }
}
export class ReportContentsItem {
    key;
    choicesIndex;
    title;
    time;
    content;
    checked;
    path;
    require;
    contentType;
    choices;
    reportVisible;
    static CONTENTS_TYPE_MASTER = [
        {
            contentType: REPORT_CONTENT_TYPE.TEXT,
            title: 'テキスト',
        },
        {
            contentType: REPORT_CONTENT_TYPE.CHOICE,
            title: '複数選択',
        },
        {
            contentType: REPORT_CONTENT_TYPE.SELECT,
            title: '単数選択',
        },
        {
            contentType: REPORT_CONTENT_TYPE.DATETIME,
            title: '日付',
        },
        {
            contentType: REPORT_CONTENT_TYPE.TENKI,
            title: '天気',
        },
        {
            contentType: REPORT_CONTENT_TYPE.TEXTAREA,
            title: 'テキストエリア',
        },
        {
            contentType: REPORT_CONTENT_TYPE.IMAGE,
            title: '写真',
        },
        {
            contentType: REPORT_CONTENT_TYPE.MOVIE,
            title: '動画',
        },
    ]; // フォーム編集時のselect要素 TODO: DBでマスター持つ?
    constructor(res) {
        this.key = res.key;
        this.choicesIndex = res.choicesIndex;
        this.title = res.title;
        this.time = res.time ?? undefined;
        this.require = res.require;
        this.contentType = res.contentType;
        this.content = res.content ?? '';
        this.checked = res.checked ?? [];
        this.path = res.path ?? '';
        this.choices = res.choices ?? [];
        this.reportVisible = res.reportVisible;
    }
    convertContentType() {
        return ReportContentsItem.CONTENTS_TYPE_MASTER.filter((c) => c.contentType === this.contentType)[0].title;
    }
    addChoice() {
        this.choices?.push({ title: '', value: String(this.choicesIndex) });
        this.choicesIndex++;
    }
    //
    updateChoice(index, data) {
        // "対象 &&"を先頭に置くことでundefinedではないことを明示
        if (this.choices && this.choices[index]) {
            this.choices[index].title = data;
        }
    }
    deleteChoice(index) {
        // "対象 &&"を先頭に置くことでundefinedではないことを明示
        if (this.choices && this.choices[index]) {
            this.choices.splice(index, 1);
        }
    }
    reset() {
        this.choices = [];
    }
    // 複数選択式の回答の各タイトルを返却
    getCheckedTitle() {
        const notSelect = '選択していない';
        if (this.checked.length < 1)
            return notSelect;
        const checkedTitle = [];
        this.choices?.forEach((c) => {
            if (this.checked?.includes(c.value)) {
                checkedTitle.push(c.title);
            }
        });
        return checkedTitle.join(', ');
    }
    // 単一選択式の回答のタイトルを返却
    getSelectTitle() {
        const notSelect = '選択していない';
        if (!this.choices)
            return notSelect; // NOTE: この関数を呼んでいる時点で選択肢がないことはあり得ないので非考慮でいい
        for (let i = 0; i < this.choices.length; i++) {
            if (this.choices[i].value == this.content) {
                return this.choices[i].title;
            }
        }
        return notSelect;
    }
    //
    hasSelected() {
        // 単一選択・複数選択か
        if (this.contentType === REPORT_CONTENT_TYPE.CHOICE ||
            this.contentType === REPORT_CONTENT_TYPE.SELECT) {
            // 選択肢が1以上ある
            if (this.choices && this.choices.length > 0) {
                const result = this.choices.filter((c) => {
                    return c.title && c.title.trim() != '';
                });
                // 選択肢タイトルに入力がある
                if (result.length === this.choices.length) {
                    return true;
                }
                else {
                    return false;
                }
            }
            else {
                // 単一選択・複数選択だが選択肢が入力されていないのでfalse
                return false;
            }
        }
        else {
            // 単一選択・複数選択でないのでtrueを返却
            return true;
        }
    }
    static getInstance(contentsKey) {
        return new ReportContentsItem({
            key: contentsKey,
            choicesIndex: 0,
            title: '',
            require: false,
            contentType: '',
            content: '',
            path: '',
            reportVisible: false,
        });
    }
}
export default ReportForm;
