import dayjs from 'dayjs';
import { DiaryModel } from './Diary';
export class MustReadModel {
    diary;
    user;
    created_at;
    updated_at;
    constructor(data) {
        this.diary = new DiaryModel(data.diary || {});
        this.user = data.user || {};
        this.created_at = data.created_at
            ? dayjs(data.created_at).format('YYYY/MM/DD HH:mm:ss')
            : '';
        this.updated_at = data.updated_at
            ? dayjs(data.updated_at).format('YYYY/MM/DD HH:mm:ss')
            : '';
    }
}
export class MustReadListModel {
    list;
    constructor() {
        this.list = [];
    }
    init(data) {
        this.clear();
        this.list.push(...data.map((d) => {
            return new MustReadModel(d);
        }));
    }
    clear() {
        this.list.splice(0);
    }
    get latestCount() {
        return this.list.filter((i) => {
            const createDate = dayjs(i.created_at);
            // // 24時間以内の必読を最新とする
            const now = dayjs().subtract(1, 'd');
            // 1時間以内の必読を最新とする
            // const now = dayjs().subtract(1, 'h');
            return createDate.isAfter(now);
        }).length;
    }
}
