import { ref, reactive, onMounted } from 'vue';
import axios from 'axios';
import { HistoryModel, HistoryListModel } from '../models/History';
const useHistory = () => {
    const loadingFlag = ref(true);
    const infiniteId = ref(0);
    const nextPage = ref('/api/history/showHistory');
    const spNextPage = ref('/api/history/spShowHistory');
    const historyList = reactive(new HistoryListModel());
    const total = ref(0);
    onMounted(() => {
        infiniteId.value = infiniteId.value + 1;
    });
    const historyLoadData = (diaryId, page) => {
        loadingFlag.value = true;
        let searchParam = {};
        searchParam.diary_id = diaryId;
        axios
            .get(page.value, { params: searchParam })
            .then((res) => {
            let data = res.data.data;
            if (!data) {
                loadingFlag.value = false;
                return;
            }
            total.value = res.data.total;
            page.value = res.data.next_page_url;
            Object.keys(data).forEach((k) => {
                historyList.contents.push(new HistoryModel(data[k]));
            });
            if (res.data.next_page_url === null) {
                loadingFlag.value = false;
            }
        })
            .catch(() => {
            loadingFlag.value = false;
        });
    };
    const loadData = (diaryId) => {
        historyLoadData(diaryId, nextPage);
    };
    const spLoadData = (diaryId) => {
        historyLoadData(diaryId, spNextPage);
    };
    return {
        loadingFlag,
        infiniteId,
        nextPage,
        historyList,
        total,
        loadData,
        spLoadData,
    };
};
export default useHistory;
